"use client";
import { useMemo,useState } from "react";
import Link from "next/link";
import { vendors } from "@/data/demo-procurement";
import { ProcurementHeader } from "../procurement-header";
import styles from "../procurement.module.css";
export function VendorsPage(){const[q,setQ]=useState("");const list=useMemo(()=>vendors.filter(v=>v.name.toLowerCase().includes(q.toLowerCase())),[q]);const summary=[["Registered Vendors","248"],["Active Participants","64"],["Documents Requiring Review","12"],["Previously Awarded","37"]];return <div className={styles.page}><ProcurementHeader context="Supplier network" title="Vendors" description="Review vendor participation, procurement evidence and supplier history."/><section className={styles.summary}>{summary.map(([a,b])=><article className={styles.summaryItem} key={a}><small>{a}</small><strong>{b}</strong></article>)}</section><div className={styles.toolbar}><input className={styles.search} aria-label="Search vendors" placeholder="Search vendors" value={q} onChange={e=>setQ(e.target.value)}/><select className={styles.select} aria-label="Participation filter"><option>All participation</option><option>Active bids</option><option>Previously awarded</option></select><select className={styles.select} aria-label="Verification filter"><option>All verification states</option><option>Validated</option><option>Requires review</option></select></div><section className={styles.panel}><div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>Vendor</th><th>Participation</th><th>Active Bids</th><th>Document Status</th><th>Previous Awards</th><th>Performance</th><th>Risk / Review</th><th /></tr></thead><tbody>{list.map(v=><tr key={v.id}><td className={styles.titleCell}><strong>{v.name}</strong><span>Supplier record · Demo data</span></td><td>{v.participation}</td><td>{v.activeBids}</td><td><span className={`${styles.status} ${v.documentStatus.includes("Review")||v.documentStatus.includes("Pending")?styles.warning:styles.success}`}>{v.documentStatus}</span></td><td>{v.awards}</td><td>{v.performance}</td><td>{v.risk}</td><td>{v.id==="apex-infra"?<Link className={styles.action} href="/organization/vendors/apex-infra">Open →</Link>:"View"}</td></tr>)}</tbody></table></div></section></div>}
